//! Port of the sort-variant template shared by go1.27.1
//! `src/sort/zsortinterface.go`, `src/sort/zsortfunc.go`,
//! `src/slices/zsortanyfunc.go` and `src/slices/zsortordered.go`.
//!
//! All four files are generated by `src/sort/gen_sort_variants.go` from one
//! template and differ only in how "less" and "swap" are spelled:
//!
//! | Go variant            | less(i, j)                         | swap(i, j)               |
//! |-----------------------|------------------------------------|--------------------------|
//! | zsortinterface.go     | `data.Less(i, j)`                  | `data.Swap(i, j)`        |
//! | zsortfunc.go          | `data.Less(i, j)` (lessSwap)       | `data.Swap(i, j)`        |
//! | zsortanyfunc.go       | `cmp(data[i], data[j]) < 0`        | `data[i], data[j] = ...` |
//! | zsortordered.go       | `cmp.Less(data[i], data[j])`       | `data[i], data[j] = ...` |
//!
//! The sequence of less/swap calls is therefore identical for all variants,
//! and this single port (generic over [`LessSwap`]) reproduces each of them
//! call for call. Indices are `isize` to mirror Go `int` arithmetic exactly.

/// The two primitives every variant is built on.
pub(crate) trait LessSwap {
    fn less(&mut self, i: isize, j: isize) -> bool;
    fn swap(&mut self, i: isize, j: isize);
}

// Go: sort/sort.go:sortedHint
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum SortedHint {
    Unknown,
    Increasing,
    Decreasing,
}

// Go: sort/sort.go:xorshift
struct Xorshift(u64);

impl Xorshift {
    // Go: sort/sort.go:xorshift.Next
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        self.0
    }
}

/// Go `bits.Len(uint(x))`.
pub(crate) fn bits_len(x: isize) -> isize {
    let x = x as usize;
    (usize::BITS - x.leading_zeros()) as isize
}

// Go: sort/sort.go:nextPowerOfTwo
fn next_power_of_two(length: isize) -> usize {
    let shift = bits_len(length) as u32;
    // Go: uint(1 << shift); a shift >= 64 yields 0.
    1usize.checked_shl(shift).unwrap_or(0)
}

// Go: sort/zsortinterface.go:insertionSort
/// insertionSort sorts data[a:b] using insertion sort.
pub(crate) fn insertion_sort<D: LessSwap + ?Sized>(data: &mut D, a: isize, b: isize) {
    let mut i = a + 1;
    while i < b {
        let mut j = i;
        while j > a && data.less(j, j - 1) {
            data.swap(j, j - 1);
            j -= 1;
        }
        i += 1;
    }
}

// Go: sort/zsortinterface.go:siftDown
/// siftDown implements the heap property on data[lo:hi].
/// first is an offset into the array where the root of the heap lies.
fn sift_down<D: LessSwap + ?Sized>(data: &mut D, lo: isize, hi: isize, first: isize) {
    let mut root = lo;
    loop {
        let mut child = 2 * root + 1;
        if child >= hi {
            break;
        }
        if child + 1 < hi && data.less(first + child, first + child + 1) {
            child += 1;
        }
        if !data.less(first + root, first + child) {
            return;
        }
        data.swap(first + root, first + child);
        root = child;
    }
}

// Go: sort/zsortinterface.go:heapSort
fn heap_sort<D: LessSwap + ?Sized>(data: &mut D, a: isize, b: isize) {
    let first = a;
    let lo = 0;
    let hi = b - a;

    // Build heap with greatest element at top.
    let mut i = (hi - 1) / 2;
    while i >= 0 {
        sift_down(data, i, hi, first);
        i -= 1;
    }

    // Pop elements, largest first, into end of data.
    let mut i = hi - 1;
    while i >= 0 {
        data.swap(first, first + i);
        sift_down(data, lo, i, first);
        i -= 1;
    }
}

// Go: sort/zsortinterface.go:pdqsort
/// pdqsort sorts data[a:b].
/// The algorithm based on pattern-defeating quicksort(pdqsort), but without the optimizations from BlockQuicksort.
/// pdqsort paper: https://arxiv.org/pdf/2106.05123.pdf
/// C++ implementation: https://github.com/orlp/pdqsort
/// Rust implementation: https://docs.rs/pdqsort/latest/pdqsort/
/// limit is the number of allowed bad (very unbalanced) pivots before falling back to heapsort.
pub(crate) fn pdqsort<D: LessSwap + ?Sized>(data: &mut D, a: isize, b: isize, limit: isize) {
    const MAX_INSERTION: isize = 12;

    let mut a = a;
    let mut b = b;
    let mut limit = limit;
    let mut was_balanced = true; // whether the last partitioning was reasonably balanced
    let mut was_partitioned = true; // whether the slice was already partitioned

    loop {
        let length = b - a;

        if length <= MAX_INSERTION {
            insertion_sort(data, a, b);
            return;
        }

        // Fall back to heapsort if too many bad choices were made.
        if limit == 0 {
            heap_sort(data, a, b);
            return;
        }

        // If the last partitioning was imbalanced, we need to breaking patterns.
        if !was_balanced {
            break_patterns(data, a, b);
            limit -= 1;
        }

        let (mut pivot, mut hint) = choose_pivot(data, a, b);
        if hint == SortedHint::Decreasing {
            reverse_range(data, a, b);
            // The chosen pivot was pivot-a elements after the start of the array.
            // After reversing it is pivot-a elements before the end of the array.
            // The idea came from Rust's implementation.
            pivot = (b - 1) - (pivot - a);
            hint = SortedHint::Increasing;
        }

        // The slice is likely already sorted.
        if was_balanced
            && was_partitioned
            && hint == SortedHint::Increasing
            && partial_insertion_sort(data, a, b)
        {
            return;
        }

        // Probably the slice contains many duplicate elements, partition the slice into
        // elements equal to and elements greater than the pivot.
        if a > 0 && !data.less(a - 1, pivot) {
            let mid = partition_equal(data, a, b, pivot);
            a = mid;
            continue;
        }

        let (mid, already_partitioned) = partition(data, a, b, pivot);
        was_partitioned = already_partitioned;

        let (left_len, right_len) = (mid - a, b - mid);
        let balance_threshold = length / 8;
        if left_len < right_len {
            was_balanced = left_len >= balance_threshold;
            pdqsort(data, a, mid, limit);
            a = mid + 1;
        } else {
            was_balanced = right_len >= balance_threshold;
            pdqsort(data, mid + 1, b, limit);
            b = mid;
        }
    }
}

// Go: sort/zsortinterface.go:partition
/// partition does one quicksort partition.
/// Let p = data[pivot]
/// Moves elements in data[a:b] around, so that data[i]<p and data[j]>=p for i<newpivot and j>newpivot.
/// On return, data[newpivot] = p
fn partition<D: LessSwap + ?Sized>(
    data: &mut D,
    a: isize,
    b: isize,
    pivot: isize,
) -> (isize, bool) {
    data.swap(a, pivot);
    let (mut i, mut j) = (a + 1, b - 1); // i and j are inclusive of the elements remaining to be partitioned

    while i <= j && data.less(i, a) {
        i += 1;
    }
    while i <= j && !data.less(j, a) {
        j -= 1;
    }
    if i > j {
        data.swap(j, a);
        return (j, true);
    }
    data.swap(i, j);
    i += 1;
    j -= 1;

    loop {
        while i <= j && data.less(i, a) {
            i += 1;
        }
        while i <= j && !data.less(j, a) {
            j -= 1;
        }
        if i > j {
            break;
        }
        data.swap(i, j);
        i += 1;
        j -= 1;
    }
    data.swap(j, a);
    (j, false)
}

// Go: sort/zsortinterface.go:partitionEqual
/// partitionEqual partitions data[a:b] into elements equal to data[pivot] followed by elements greater than data[pivot].
/// It assumed that data[a:b] does not contain elements smaller than the data[pivot].
fn partition_equal<D: LessSwap + ?Sized>(data: &mut D, a: isize, b: isize, pivot: isize) -> isize {
    data.swap(a, pivot);
    let (mut i, mut j) = (a + 1, b - 1); // i and j are inclusive of the elements remaining to be partitioned

    loop {
        while i <= j && !data.less(a, i) {
            i += 1;
        }
        while i <= j && data.less(a, j) {
            j -= 1;
        }
        if i > j {
            break;
        }
        data.swap(i, j);
        i += 1;
        j -= 1;
    }
    i
}

// Go: sort/zsortinterface.go:partialInsertionSort
/// partialInsertionSort partially sorts a slice, returns true if the slice is sorted at the end.
fn partial_insertion_sort<D: LessSwap + ?Sized>(data: &mut D, a: isize, b: isize) -> bool {
    const MAX_STEPS: isize = 5; // maximum number of adjacent out-of-order pairs that will get shifted
    const SHORTEST_SHIFTING: isize = 50; // don't shift any elements on short arrays
    let mut i = a + 1;
    for _ in 0..MAX_STEPS {
        while i < b && !data.less(i, i - 1) {
            i += 1;
        }

        if i == b {
            return true;
        }

        if b - a < SHORTEST_SHIFTING {
            return false;
        }

        data.swap(i, i - 1);

        // Shift the smaller one to the left.
        if i - a >= 2 {
            // Note: Go's bound is `j >= 1`, not `j > a`; kept verbatim.
            let mut j = i - 1;
            while j >= 1 {
                if !data.less(j, j - 1) {
                    break;
                }
                data.swap(j, j - 1);
                j -= 1;
            }
        }
        // Shift the greater one to the right.
        if b - i >= 2 {
            let mut j = i + 1;
            while j < b {
                if !data.less(j, j - 1) {
                    break;
                }
                data.swap(j, j - 1);
                j += 1;
            }
        }
    }
    false
}

// Go: sort/zsortinterface.go:breakPatterns
/// breakPatterns scatters some elements around in an attempt to break some patterns
/// that might cause imbalanced partitions in quicksort.
fn break_patterns<D: LessSwap + ?Sized>(data: &mut D, a: isize, b: isize) {
    let length = b - a;
    if length >= 8 {
        let mut random = Xorshift(length as u64);
        let modulus = next_power_of_two(length);

        let mut idx = a + (length / 4) * 2 - 1;
        while idx <= a + (length / 4) * 2 + 1 {
            let mut other = ((random.next() as usize) & (modulus.wrapping_sub(1))) as isize;
            if other >= length {
                other -= length;
            }
            data.swap(idx, a + other);
            idx += 1;
        }
    }
}

// Go: sort/zsortinterface.go:choosePivot
/// choosePivot chooses a pivot in data[a:b].
///
/// [0,8): chooses a static pivot.
/// [8,shortestNinther): uses the simple median-of-three method.
/// [shortestNinther,∞): uses the Tukey ninther method.
fn choose_pivot<D: LessSwap + ?Sized>(data: &mut D, a: isize, b: isize) -> (isize, SortedHint) {
    const SHORTEST_NINTHER: isize = 50;
    const MAX_SWAPS: isize = 4 * 3;

    let l = b - a;

    let mut swaps: isize = 0;
    let mut i = a + l / 4;
    let mut j = a + l / 4 * 2;
    let mut k = a + l / 4 * 3;

    if l >= 8 {
        if l >= SHORTEST_NINTHER {
            // Tukey ninther method, the idea came from Rust's implementation.
            i = median_adjacent(data, i, &mut swaps);
            j = median_adjacent(data, j, &mut swaps);
            k = median_adjacent(data, k, &mut swaps);
        }
        // Find the median among i, j, k and stores it into j.
        j = median(data, i, j, k, &mut swaps);
    }

    match swaps {
        0 => (j, SortedHint::Increasing),
        MAX_SWAPS => (j, SortedHint::Decreasing),
        _ => (j, SortedHint::Unknown),
    }
}

// Go: sort/zsortinterface.go:order2
/// order2 returns x,y where data[x] <= data[y], where x,y=a,b or x,y=b,a.
fn order2<D: LessSwap + ?Sized>(
    data: &mut D,
    a: isize,
    b: isize,
    swaps: &mut isize,
) -> (isize, isize) {
    if data.less(b, a) {
        *swaps += 1;
        return (b, a);
    }
    (a, b)
}

// Go: sort/zsortinterface.go:median
/// median returns x where data[x] is the median of data[a],data[b],data[c], where x is a, b, or c.
fn median<D: LessSwap + ?Sized>(
    data: &mut D,
    a: isize,
    b: isize,
    c: isize,
    swaps: &mut isize,
) -> isize {
    let (a, b) = order2(data, a, b, swaps);
    let (b, _c) = order2(data, b, c, swaps);
    let (_a, b) = order2(data, a, b, swaps);
    b
}

// Go: sort/zsortinterface.go:medianAdjacent
/// medianAdjacent finds the median of data[a - 1], data[a], data[a + 1] and stores the index into a.
fn median_adjacent<D: LessSwap + ?Sized>(data: &mut D, a: isize, swaps: &mut isize) -> isize {
    median(data, a - 1, a, a + 1, swaps)
}

// Go: sort/zsortinterface.go:reverseRange
fn reverse_range<D: LessSwap + ?Sized>(data: &mut D, a: isize, b: isize) {
    let mut i = a;
    let mut j = b - 1;
    while i < j {
        data.swap(i, j);
        i += 1;
        j -= 1;
    }
}

// Go: sort/zsortinterface.go:swapRange
fn swap_range<D: LessSwap + ?Sized>(data: &mut D, a: isize, b: isize, n: isize) {
    for i in 0..n {
        data.swap(a + i, b + i);
    }
}

// Go: sort/zsortinterface.go:stable
pub(crate) fn stable<D: LessSwap + ?Sized>(data: &mut D, n: isize) {
    let mut block_size: isize = 20; // must be > 0
    let (mut a, mut b) = (0isize, block_size);
    while b <= n {
        insertion_sort(data, a, b);
        a = b;
        b += block_size;
    }
    insertion_sort(data, a, n);

    while block_size < n {
        a = 0;
        b = 2 * block_size;
        while b <= n {
            sym_merge(data, a, a + block_size, b);
            a = b;
            b += 2 * block_size;
        }
        let m = a + block_size;
        if m < n {
            sym_merge(data, a, m, n);
        }
        block_size *= 2;
    }
}

// Go: sort/zsortinterface.go:symMerge
/// symMerge merges the two sorted subsequences data[a:m] and data[m:b] using
/// the SymMerge algorithm from Pok-Son Kim and Arne Kutzner, "Stable Minimum
/// Storage Merging by Symmetric Comparisons", in Susanne Albers and Tomasz
/// Radzik, editors, Algorithms - ESA 2004, volume 3221 of Lecture Notes in
/// Computer Science, pages 714-723. Springer, 2004.
///
/// symMerge assumes non-degenerate arguments: a < m && m < b.
fn sym_merge<D: LessSwap + ?Sized>(data: &mut D, a: isize, m: isize, b: isize) {
    // Avoid unnecessary recursions of symMerge
    // by direct insertion of data[a] into data[m:b]
    // if data[a:m] only contains one element.
    if m - a == 1 {
        // Use binary search to find the lowest index i
        // such that data[i] >= data[a] for m <= i < b.
        // Exit the search loop with i == b in case no such index exists.
        let mut i = m;
        let mut j = b;
        while i < j {
            let h = ((i + j) as usize >> 1) as isize;
            if data.less(h, a) {
                i = h + 1;
            } else {
                j = h;
            }
        }
        // Swap values until data[a] reaches the position before i.
        let mut k = a;
        while k < i - 1 {
            data.swap(k, k + 1);
            k += 1;
        }
        return;
    }

    // Avoid unnecessary recursions of symMerge
    // by direct insertion of data[m] into data[a:m]
    // if data[m:b] only contains one element.
    if b - m == 1 {
        // Use binary search to find the lowest index i
        // such that data[i] > data[m] for a <= i < m.
        // Exit the search loop with i == m in case no such index exists.
        let mut i = a;
        let mut j = m;
        while i < j {
            let h = ((i + j) as usize >> 1) as isize;
            if !data.less(m, h) {
                i = h + 1;
            } else {
                j = h;
            }
        }
        // Swap values until data[m] reaches the position i.
        let mut k = m;
        while k > i {
            data.swap(k, k - 1);
            k -= 1;
        }
        return;
    }

    let mid = ((a + b) as usize >> 1) as isize;
    let n = mid + m;
    let (mut start, mut r);
    if m > mid {
        start = n - b;
        r = mid;
    } else {
        start = a;
        r = m;
    }
    let p = n - 1;

    while start < r {
        let c = ((start + r) as usize >> 1) as isize;
        if !data.less(p - c, c) {
            start = c + 1;
        } else {
            r = c;
        }
    }

    let end = n - start;
    if start < m && m < end {
        rotate(data, start, m, end);
    }
    if a < start && start < mid {
        sym_merge(data, a, start, mid);
    }
    if mid < end && end < b {
        sym_merge(data, mid, end, b);
    }
}

// Go: sort/zsortinterface.go:rotate
/// rotate rotates two consecutive blocks u = data[a:m] and v = data[m:b] in data:
/// Data of the form 'x u v y' is changed to 'x v u y'.
/// rotate performs at most b-a many calls to data.Swap,
/// and it assumes non-degenerate arguments: a < m && m < b.
fn rotate<D: LessSwap + ?Sized>(data: &mut D, a: isize, m: isize, b: isize) {
    let mut i = m - a;
    let mut j = b - m;

    while i != j {
        if i > j {
            swap_range(data, m - i, m, j);
            i -= j;
        } else {
            swap_range(data, m - i, m + j - i, i);
            j -= i;
        }
    }
    // i == j
    swap_range(data, m - i, m, i);
}
